metrics.workdir_dsl:
workspace "Bookshop" "A simple online bookshop" {

    model {
        customer = person "Customer" "A customer who browses and buys books"

        bookshop = softwareSystem "Bookshop" "An online bookshop for browsing and ordering books" {
            webStore = container "Web Store" "The web application customers use to browse books and place orders" "Java/Spring"
            orderProcessor = container "Order Processor" "Processes orders and coordinates fulfilment" "Java"
        }

        customer -> webStore "Browses books and places orders through" "HTTPS"
        webStore -> orderProcessor "Submits new orders to" "gRPC"
    }

    views {
        systemContext bookshop "BookshopContext" "System context for the Bookshop" {
            include *
            autoLayout
            title "System Context for Bookshop"
        }
    }
}
